///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 법인명 입력란에 포커스를 준다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function(e) {
    try {
        ibx_comAbbrv.focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료점 — 현재 별도의 종료 로직은 없다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ibx_coSnm_onkeydown
 * @description 기업명 입력란 keydown — 엔터키(13) 입력 시 기업목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_coSnm_onkeydown(e);
 */
scwin.ibx_coSnm_onkeydown = function(e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.ibx_coSnm_onkeydown" });
    }
};

/**
 * @method
 * @name btn_stdIndCd_onclick
 * @description 업종검색 버튼 클릭 — 업종검색 팝업을 오픈한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_stdIndCd_onclick();
 */
scwin.btn_stdIndCd_onclick = function() {
    try {
        // 업종검색 팝업 오픈
        scwin.fn_StdIndSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.btn_stdIndCd_onclick" });
    }
};

/**
 * @method
 * @name btn_affCoCd_onclick
 * @description 기업집단검색 버튼 클릭 — 기업집단검색 팝업을 오픈한다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_affCoCd_onclick();
 */
scwin.btn_affCoCd_onclick = function() {
    try {
        // 기업집단검색 팝업 오픈
        scwin.fn_AffCoCdSrchOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.btn_affCoCd_onclick" });
    }
};

/**
 * @method
 * @name ibx_entprGrpNm_onkeydown
 * @description 기업집단명 입력란 keydown — 엔터키(13) 입력 시 기업집단검색 팝업을 오픈한다.
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_entprGrpNm_onkeydown();
 */
scwin.ibx_entprGrpNm_onkeydown = function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            scwin.fn_AffCoCdSrchOpen();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.ibx_entprGrpNm_onkeydown" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description [조회] 버튼 클릭 — 검색조건을 이용한 법인정보를 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_Search_onclick(e);
 */
scwin.img_Search_onclick = function (e) {
    try {
        // 조회 버튼 클릭
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description [닫기] 버튼 클릭 — 팝업화면을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.img_Close_onclick(e);
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_Search_onkeydown
 * @description 법인명 입력란 keydown — 해당 키 값이 엔터키(13)일 경우 조회 로직을 처리한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.txb_Search_onkeydown(e);
 */
scwin.txb_Search_onkeydown = function (e) {
    try {
        // 기업명 엔터
        if (e.keyCode === 13) {
            scwin.search();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.txb_Search_onkeydown" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description 법인정보 그리드 행 더블클릭 — 선택한 행의 법인 정보를 부모창(오프너)에 전달한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_IsuInst_oncelldblclick(0, 0, "isurCd");
 */
scwin.grd_IsuInst_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.setParam(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF99001.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name sbm_comList_submitdone
 * @description 기업목록 조회 완료 콜백 — 응답 데이터를 목록에 반영하고 총건수를 표시한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_comList_submitdone(e);
 */
scwin.sbm_comList_submitdone = function (e) {
    // if (dlt_comListRes.errorMsg) {
    //     alert(dlt_comListRes.errorMsg);
    // } else {
    //     tbx_totCnt.setValue("총 " + rowcount + " 건");
    // }
    dlt_comListRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_comListRes.getRowCount());
};

/**
 * @method
 * @name sbm_isurList_submitdone
 * @description 법인정보 조회(sbm_isurList) 완료 콜백 — 응답 데이터를 목록에 반영하고 총건수를 표시한다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_isurList_submitdone(e);
 */
scwin.sbm_isurList_submitdone = function (e) {
    dataResList.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dataResList.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화. 조회 목록을 비우고 총건수를 0으로 표시한다.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dataResList.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크(필수항목 체크) — 현재 별도의 체크 로직은 없다.
 * @returns {void}
 * @hidden N
 * @example scwin.chkValid();
 */
scwin.chkValid = function() {
    // 필수항목 체크.

};

/**
 * @method
 * @name search
 * @description 기업목록 조회 — 데이터셋 초기화·조회조건 필수 체크 후 법인명 검색조건으로 법인정보를 조회한다.
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {

    }

    const reqMap = {
        comNm: ibx_comAbbrv.getValue() // 기업명
    };
    $c.sbm.execute(sbm_isurList, reqMap);
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다. 행 인덱스 미지정 시 현재 선택 행을 사용하며, 해당 행의 법인 정보를 팝업 결과로 넘기고 팝업을 닫는다.
 * @param {Number} v_Currow 전달할 행 인덱스(미지정 시 현재 선택 행)
 * @returns {void}
 * @hidden N
 * @example scwin.setParam(0);
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dataResList.getRowPosition();
    }

    const res = dataResList.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

/**
 * @method
 * @name gform_onload
 * @description 폼 로드 초기화 — 현재 별도의 초기화 로직은 없다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
};
